var pad = 34;
var Ls = [0.40, 0.60, 0.80, 1.00, 1.20];
var g = p.g, n = p.power;
var ys = [], i;
for (i = 0; i < Ls.length; i++) {
  var T = 2 * Math.PI * Math.sqrt(Ls[i] / g);
  ys.push(Math.pow(T, n));
}
var maxX = 1.35;
var maxY = ys[ys.length - 1] * 1.2;
var X = function (x) { return pad + x / maxX * (W - pad - 14); };
var Y = function (y) { return H - pad - y / maxY * (H - pad - 16); };

ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(X(0), Y(maxY)); ctx.lineTo(X(0), Y(0)); ctx.lineTo(X(maxX), Y(0));
ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.ink;
ctx.fillText("L (m)", W - 52, H - 12);
var ylab = n === 1 ? "T (s)" : "T^" + n + " (s^" + n + ")";
ctx.save();
ctx.translate(12, 26);
ctx.fillText(ylab, 0, 0);
ctx.restore();

// straight reference line from the origin through the last point
var slope = ys[ys.length - 1] / Ls[Ls.length - 1];
ctx.strokeStyle = C.faint;
ctx.setLineDash([4, 4]);
ctx.beginPath();
ctx.moveTo(X(0), Y(0));
ctx.lineTo(X(maxX), Y(slope * maxX));
ctx.stroke();
ctx.setLineDash([]);

// worst fractional departure from that straight line
var worst = 0;
for (i = 0; i < Ls.length; i++) {
  var lineY = slope * Ls[i];
  var d = Math.abs(ys[i] - lineY) / lineY;
  if (d > worst) worst = d;
}

var lit = Math.floor(t * 1.2) % Ls.length;
for (i = 0; i < Ls.length; i++) {
  ctx.fillStyle = i === lit ? C.accent : C.figure;
  ctx.beginPath();
  ctx.arc(X(Ls[i]), Y(ys[i]), i === lit ? 6 : 4, 0, Math.PI * 2);
  ctx.fill();
}
ctx.fillStyle = C.ink;
ctx.fillText("L = " + Ls[lit].toFixed(2) + " m,  y = " + ys[lit].toFixed(3),
             X(0) + 12, Y(maxY) + 14);

out.note = "plotting T^" + n + " against L: worst departure from a straight line through the origin is "
  + (worst * 100).toFixed(1) + "%  (slope " + slope.toFixed(3) + ")";

var pad = 38;
var tmax = 9, vmax = 5;
var X = function (x) { return pad + x / tmax * (W - pad - 18); };
var Y = function (y) { return H - pad - y / vmax * (H - pad - 24); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(X(0), Y(vmax)); ctx.lineTo(X(0), Y(0)); ctx.lineTo(X(tmax), Y(0));
ctx.stroke();

// the area under the graph
ctx.fillStyle = C.faint;
ctx.globalAlpha = 0.45;
ctx.beginPath();
ctx.moveTo(X(0), Y(0));
ctx.lineTo(X(2), Y(4));
ctx.lineTo(X(6), Y(4));
ctx.lineTo(X(8), Y(0));
ctx.closePath();
ctx.fill();
ctx.globalAlpha = 1;

// the graph itself
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(X(0), Y(0));
ctx.lineTo(X(2), Y(4));
ctx.lineTo(X(6), Y(4));
ctx.lineTo(X(8), Y(0));
ctx.stroke();

// slope triangle on the rising segment
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.2;
ctx.setLineDash([3, 3]);
ctx.beginPath();
ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(2), Y(0)); ctx.lineTo(X(2), Y(4));
ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.ink;
ctx.fillText("run 2.0 s", X(0) + 6, Y(0) + 14);
ctx.fillText("rise 4.0 m/s", X(2) + 6, Y(2));
ctx.fillText("slope = a = 2.0 m/s^2", X(0) + 6, Y(vmax) + 14);
ctx.fillStyle = C.figure;
ctx.fillText("area = displacement = 24 m", X(2.4), Y(1.6));
ctx.fillStyle = C.ink;
ctx.fillText("t (s)", W - 40, H - 12);
ctx.fillText("v (m/s)", X(0) + 6, Y(vmax) - 6);

// axis ticks
var i;
for (i = 0; i <= 8; i += 2) {
  ctx.strokeStyle = C.rule;
  ctx.beginPath(); ctx.moveTo(X(i), Y(0)); ctx.lineTo(X(i), Y(0) + 4); ctx.stroke();
  ctx.fillStyle = C.ink;
  ctx.fillText(String(i), X(i) - 3, Y(0) + 17);
}
for (i = 2; i <= 4; i += 2) {
  ctx.strokeStyle = C.rule;
  ctx.beginPath(); ctx.moveTo(X(0), Y(i)); ctx.lineTo(X(0) - 4, Y(i)); ctx.stroke();
  ctx.fillStyle = C.ink;
  ctx.fillText(String(i), X(0) - 16, Y(i) + 4);
}

var N = Math.round(p.N), sigma = p.sigma, i;
var pad = 36;
var truth = 2.30;

// deterministic pseudo-noise: no Math.random anywhere
function wob(k) {
  var s = Math.sin(k * 12.9898) * 43758.5453;
  var u = s - Math.floor(s);
  var s2 = Math.sin(k * 78.233 + 1.7) * 12345.6789;
  var u2 = s2 - Math.floor(s2);
  var s3 = Math.sin(k * 39.425 + 4.1) * 9876.54321;
  var u3 = s3 - Math.floor(s3);
  return (u + u2 + u3 - 1.5) * 2;
}

var vals = [];
for (i = 0; i < N; i++) vals.push(truth + sigma * wob(i + 1));

var shown = Math.min(N, 3 + Math.floor(t * 6));
var sum = 0;
for (i = 0; i < N; i++) sum += vals[i];
var mean = sum / N;
var ss = 0;
for (i = 0; i < N; i++) ss += (vals[i] - mean) * (vals[i] - mean);
var sd = N > 1 ? Math.sqrt(ss / (N - 1)) : 0;
var se = sd / Math.sqrt(N);

var lo = truth - 3.2 * 0.6, hi = truth + 3.2 * 0.6;
var X = function (k) { return pad + (k + 0.5) / Math.max(N, 6) * (W - pad - 16); };
var Y = function (v) { return H - pad - (v - lo) / (hi - lo) * (H - pad - 18); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(X(-0.5), Y(hi)); ctx.lineTo(X(-0.5), Y(lo)); ctx.lineTo(W - 10, Y(lo));
ctx.stroke();

// the band one standard error wide either side of the mean
ctx.fillStyle = C.accent;
ctx.globalAlpha = 0.25;
ctx.fillRect(X(-0.5), Y(mean + se), W - 10 - X(-0.5), Y(mean - se) - Y(mean + se));
ctx.globalAlpha = 1;

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(X(-0.5), Y(mean)); ctx.lineTo(W - 10, Y(mean)); ctx.stroke();

ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(-0.5), Y(truth)); ctx.lineTo(W - 10, Y(truth)); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.figure;
for (i = 0; i < shown; i++) {
  ctx.beginPath(); ctx.arc(X(i), Y(vals[i]), 3, 0, Math.PI * 2); ctx.fill();
}

ctx.fillStyle = C.ink;
ctx.fillText("period (s)", X(-0.5) + 6, Y(hi) - 4);
ctx.fillText("trial number", W - 92, H - 12);
ctx.fillText("mean " + mean.toFixed(3) + " s", X(-0.5) + 6, Y(mean) - 6);
ctx.fillStyle = C.figure;
ctx.fillText("true value", W - 78, Y(truth) + 14);

out.note = "N = " + N + ",  s = " + sd.toFixed(3) + " s,  standard error = s/sqrt(N) = " + se.toFixed(4) + " s";
